import{_ as l,C as h,o as r,c as u,a9 as i,b as o,w as t,a as n,E as s,a8 as d,j as c}from"./chunks/framework.BOiBTRPC.js";const k=JSON.parse('{"title":"Cracking the DE Interview","description":"The senior data-engineering interview track — loop anatomy, timed SQL and coding rounds, data-platform system design, and rapid-fire drills. Communication under time pressure, not trivia.","frontmatter":{"title":"Cracking the DE Interview","description":"The senior data-engineering interview track — loop anatomy, timed SQL and coding rounds, data-platform system design, and rapid-fire drills. Communication under time pressure, not trivia."},"headers":[],"relativePath":"interview/index.md","filePath":"interview/index.md"}'),m={name:"interview/index.md"};function p(g,e,f,w,y,b){const a=h("Mermaid");return r(),u("div",null,[e[2]||(e[2]=i('<h1 id="cracking-the-de-interview" tabindex="-1">Cracking the DE Interview <a class="header-anchor" href="#cracking-the-de-interview" aria-label="Permalink to &quot;Cracking the DE Interview&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — Senior DE interviews don&#39;t test whether you know SQL; they test whether you can <em>narrate correct trade-offs in 45 minutes while someone watches</em>. Plenty of strong engineers fail loops because they&#39;ve never practiced producing an answer under time pressure, out loud, on demand.</p></blockquote><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><p>Senior data engineers, staff candidates, and solution architects heading into loops at companies where &quot;data engineering&quot; means pipeline ownership, not dashboard maintenance. You already have the technical content — the other ten tracks cover it. This track covers the <em>delivery</em>: what each round filters for, how to structure an answer, what interviewers score, and where candidates actually lose points.</p><h2 id="how-this-differs-from-memorizing" tabindex="-1">How this differs from memorizing <a class="header-anchor" href="#how-this-differs-from-memorizing" aria-label="Permalink to &quot;How this differs from memorizing&quot;">​</a></h2><p>An interview is a compressed simulation of working with you. The interviewer can&#39;t see your six months of production judgment, so they proxy it with three signals:</p><ol><li><strong>Do you clarify before building?</strong> Restating the grain, the edge cases, the constraints — in the first two minutes, not after a wrong answer.</li><li><strong>Do you trade off explicitly?</strong> &quot;I&#39;d dedupe on event_id rather than timestamp because retries shift timestamps&quot; beats a silently-correct query.</li><li><strong>Do you recover?</strong> A senior candidate who writes a bug, spots it, and narrates the fix scores higher than one who never errs but never narrates.</li></ol><p>Everything in this track is organized around those signals.</p><h2 id="how-the-chapters-fit" tabindex="-1">How the chapters fit <a class="header-anchor" href="#how-the-chapters-fit" aria-label="Permalink to &quot;How the chapters fit&quot;">​</a></h2>',9)),(r(),o(d,null,{default:t(()=>[s(a,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22Playbook%20%E2%80%94%20loop%20anatomy%2C%3Cbr%2F%3Eprep%20plan%2C%20story%20bank%22%5D%20--%3E%20B%5B%22SQL%20and%20Coding%20%E2%80%94%3Cbr%2F%3Etimed%20problem%20delivery%22%5D%0A%20%20%20%20A%20--%3E%20C%5B%22System%20Design%20%E2%80%94%3Cbr%2F%3Ethe%2045-min%20architecture%20round%22%5D%0A%20%20%20%20B%20--%3E%20D%5B%22Rapid%20Fire%20%E2%80%94%3Cbr%2F%3Efluency%20drills%22%5D%0A%20%20%20%20C%20--%3E%20D%0A%20%20%20%20A%20-.-%3E%7C%22every%20round%20feeds%3Cbr%2F%3Ethe%20same%20signal%22%7C%20D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=c("p",null,"The loop itself, mapped to where this track helps:",-1)),(r(),o(d,null,{default:t(()=>[s(a,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22Recruiter%20screen%3Cbr%2F%3Eplaybook%3A%20scope%20%2B%20level%22%5D%20--%3E%20B%5B%22Tech%20screen%3Cbr%2F%3Esql-coding%3A%20timed%20delivery%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22Onsite%3A%20SQL%3Cbr%2F%3Esql-coding%20drills%22%5D%0A%20%20%20%20B%20--%3E%20D%5B%22Onsite%3A%20design%3Cbr%2F%3Esystem-design%20framework%22%5D%0A%20%20%20%20B%20--%3E%20E%5B%22Onsite%3A%20behavioral%3Cbr%2F%3Eplaybook%3A%20story%20bank%22%5D%0A%20%20%20%20C%20%26%20D%20%26%20E%20--%3E%20F%5B%22Debrief%20%2B%20offer%3Cbr%2F%3Eplaybook%3A%20negotiation%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><p><strong><a href="/Data-Knowledge/interview/playbook.html">The Playbook</a></strong> — The loop as it actually runs in 2024-2026: recruiter screen → technical screen → onsite rounds (SQL/coding, system design, behavioral, sometimes ML or cloud depth), with what each round really filters for. Includes a 4-8 week prep plan, résumé rules that survive follow-up questions, a STAR story bank built for DEs (migration, incident, cost save), mid-vs-senior-vs-staff signal differences, red flags interviewers note, and a negotiation brief.</p><p><strong><a href="/Data-Knowledge/interview/sql-coding.html">SQL &amp; Coding Rounds</a></strong> — The timed round, deconstructed: what&#39;s actually asked (top-N-per-group, dedup, funnels, sessionization; Python generators, dict/set work, pandas/polars transforms), worked walkthroughs with minute-by-minute narration, eight practice problems with hints and full solutions, the failure modes that sink candidates, and the rubric interviewers score you on.</p><p><strong><a href="/Data-Knowledge/interview/system-design.html">System Design Round</a></strong> — The data-platform design round: a 45-minute framework (requirements → estimation → high-level → deep dives → bottlenecks) and three fully worked designs — a real-time analytics pipeline, a zero-downtime CDC migration of a 2TB OLTP database, and a metrics/feature platform serving BI and ML — each with capacity math, trade-off decision points, failure modes, and the follow-up questions interviewers ask.</p><p><strong><a href="/Data-Knowledge/interview/rapid-fire.html">Rapid Fire</a></strong> — Thirty quick-fire questions across fundamentals, SQL, Spark, streaming, cloud, modeling, and DataOps — each with a one-paragraph model answer you reveal after answering aloud. Fluency drills for the last 72 hours before the loop.</p><h2 id="round-→-chapter-→-drill-map" tabindex="-1">Round → chapter → drill map <a class="header-anchor" href="#round-→-chapter-→-drill-map" aria-label="Permalink to &quot;Round → chapter → drill map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Round</th><th>Chapter</th><th>What to drill</th></tr></thead><tbody><tr><td>Recruiter + hiring manager</td><td><a href="/Data-Knowledge/interview/playbook.html">Playbook</a></td><td>Level calibration, comp deflection, why-this-role</td></tr><tr><td>Technical screen</td><td><a href="/Data-Knowledge/interview/sql-coding.html">SQL &amp; Coding</a></td><td>25-min timed problems, narrated</td></tr><tr><td>Onsite coding</td><td><a href="/Data-Knowledge/interview/sql-coding.html">SQL &amp; Coding</a></td><td>The 8 problems + twist follow-ups</td></tr><tr><td>Onsite design</td><td><a href="/Data-Knowledge/interview/system-design.html">System Design</a></td><td>The 5-phase framework, one full design aloud daily</td></tr><tr><td>Behavioral</td><td><a href="/Data-Knowledge/interview/playbook.html">Playbook</a></td><td>8-12 STAR stories, 2-min versions</td></tr><tr><td>Final 72 hours</td><td><a href="/Data-Knowledge/interview/rapid-fire.html">Rapid Fire</a></td><td>All 30 Q&amp;As aloud, QuizCard sets</td></tr></tbody></table><h2 id="pareto-focus" tabindex="-1">Pareto focus <a class="header-anchor" href="#pareto-focus" aria-label="Permalink to &quot;Pareto focus&quot;">​</a></h2><p>What actually moves offer decisions:</p><ol><li><strong>Say the grain before anything else.</strong> &quot;One row per user per day&quot; — most wrong answers are unspoken wrong assumptions about grain.</li><li><strong>Narrate continuously.</strong> Silence is scored as floundering even when you&#39;re thinking correctly. Think aloud or lose credit for the thought.</li><li><strong>Timebox ruthlessly.</strong> A perfect answer to a question you weren&#39;t asked costs you the question you were.</li><li><strong>Trade-offs are the answer.</strong> At senior level there is no &quot;correct&quot; design — there&#39;s a defensible one with named costs.</li><li><strong>Numbers beat adjectives.</strong> &quot;10k events/sec, ~500B each, ~4GB/day&quot; signals you operate systems; &quot;it should scale&quot; signals you read about them.</li><li><strong>Own failure modes first.</strong> Naming what breaks before you&#39;re asked is the single strongest senior signal.</li><li><strong>Behavioral stories are data.</strong> Migration, incident, cost save, conflict — prepare 8-12 STAR stories with real numbers and reuse them across every question.</li><li><strong>The round is the product demo.</strong> You are demoing what it&#39;s like to work with you. Collaborate with the interviewer; don&#39;t perform at them.</li></ol>',10))])}const C=l(m,[["render",p]]);export{k as __pageData,C as default};
